// ==========================================
// RANKDLE
//
// Two people on screen at a time. Pick the
// better one, the loser gets swapped out for
// a new face, and nobody shows up twice in
// the same session. Ten picks in, the site
// turns what you chose - and what you turned
// down - into a personality read.
//
// Requires people.js (generated by tools/build.mjs)
// to be loaded first.
// ==========================================


// ------------------------------------------
// CONFIG
// ------------------------------------------

const STORAGE_PREFIX = "rankdle:v2:";

// How many picks a run is worth. Ten is long enough for a
// pattern and short enough to finish on a phone.
const ROUNDS_TOTAL = 10;

// Timing of a pick: the chosen card holds just long enough to read as
// a pick (HOLD), the loser fades (FADE), the winner holds a beat
// longer (SWAP), and then the next matchup rises in.
const HOLD_DELAY = 240;
const FADE_DELAY = 400;
const SWAP_DELAY = 150;


// ------------------------------------------
// DATA
//
// people.js gives the roster; ratings.js (generated from
// ratings.json) gives the six game ratings keyed by name.
// Merge them once here so every part of the game can score
// people directly. Anyone without ratings gets neutral ones.
// ------------------------------------------

const RATINGS_TABLE = typeof RATINGS !== "undefined" ? RATINGS : {};

const NEUTRAL_RATINGS = { fame: 3, era: 3, morality: 3, controversy: 3, gender: 0, fiction: 0 };

const PEOPLE = (typeof ROSTER !== "undefined" ? ROSTER : []).map((person) => ({
    ...person,
    ...NEUTRAL_RATINGS,
    ...(RATINGS_TABLE[person.name] || {})
}));


// ------------------------------------------
// STATE
// ------------------------------------------

const state = {
    key: "run",             // one run at a time, until you hit "Play again"
    slots: [null, null],    // the two people on screen, left and right
    seen: new Set(),        // names already shown this run
    picks: [],              // { chosen, rejected } for every completed pick
    done: false,            // all ten are in, the profile is on screen
    stagger: false,         // both cards rise in on the next render
    initial: true,          // the very first paint, where both cards rise in
    busy: false             // a swap is animating
};


// The pick the player is on, 1-based. Derived from the picks so a
// restored session always lines up.
function currentRound() {
    return state.picks.length + 1;
}


// ------------------------------------------
// PICKING PEOPLE (stat-driven)
//
// The opening pair is a straight random draw. After that nobody
// shows up twice in a run, and the next pair is not a random
// draw either - both cards are drawn around the person you just
// picked. Each draw flips its own coin (about 50/50, never
// alternating):
//
//   - "different" half: whoever is MOST DIFFERENT from the
//     person you kept
//   - "similar" half: whoever is MOST SIMILAR - and if the
//     person you kept is a villain, the pool shrinks to the
//     other villains first, so villains keep meeting villains
//
// All measured across the six ratings in ratings.json.
// Exact ties are broken at random.
//
// Both cards leave after every pick on purpose: ten picks should
// be ten decisions between strangers, not one card winning a
// rematch nine times in a row.
// ------------------------------------------

// Villains: real (non-fiction) people at the bottom of the
// morality scale, plus every P*rn Star.
function isVillain(person) {
    return person.tag === "P*rn Star" || (person.fiction === 0 && person.morality <= 1);
}

// Outright evil: real people at the very bottom of the morality
// scale. This is the one the profile calls out by name.
function isEvil(person) {
    return person.fiction === 0 && person.morality <= 1;
}

// How different two people are, 0-30. Every stat is normalised
// to 0-1 first (so all six weigh equally) then scored in integer
// fifths: the four 0-5 stats contribute up to 5 each, gender and
// fiction up to 5 each. Integers keep tie comparisons exact.
function differenceScore(a, b) {
    return (
        Math.abs(a.fame - b.fame) +
        Math.abs(a.era - b.era) +
        Math.abs(a.morality - b.morality) +
        Math.abs(a.controversy - b.controversy) +
        5 * Math.abs(a.gender - b.gender) +
        5 * Math.abs(a.fiction - b.fiction)
    );
}


// The most different person in `pool` compared to `reference`.
// No reference (the very first card of a session) = random.
// People who are equally the most different = random among them.
function mostDifferent(pool, reference) {

    if (!pool.length) {
        return null;
    }

    if (!reference) {
        return pool[Math.floor(Math.random() * pool.length)];
    }

    let best = [];
    let bestScore = -1;

    for (const person of pool) {

        const score = differenceScore(person, reference);

        if (score > bestScore) {
            bestScore = score;
            best = [person];
        } else if (score === bestScore) {
            best.push(person);
        }
    }

    return best[Math.floor(Math.random() * best.length)];
}


// The most SIMILAR person in `pool` to `reference` (smallest
// differenceScore). Ties broken at random. No reference = random.
function mostSimilar(pool, reference) {

    if (!pool.length) {
        return null;
    }

    if (!reference) {
        return pool[Math.floor(Math.random() * pool.length)];
    }

    let best = [];
    let bestScore = Infinity;

    for (const person of pool) {

        const score = differenceScore(person, reference);

        if (score < bestScore) {
            bestScore = score;
            best = [person];
        } else if (score === bestScore) {
            best.push(person);
        }
    }

    return best[Math.floor(Math.random() * best.length)];
}


// Everybody not yet shown this run and not in `excluded`.
function eligiblePool(excluded) {
    return PEOPLE.filter(
        (person) => !state.seen.has(person.name) && !excluded.has(person.name)
    );
}


// The actual decision: flip the coin, then pick accordingly.
function chooseReplacement(excluded, reference) {

    const pool = eligiblePool(excluded);
    const wantSimilar = Math.random() < 0.5;

    // Villain kept + similar half = the pool shrinks to the
    // remaining villains, so Hitler, Stalin, Saddam, Epstein
    // and the P*rn Stars keep ending up face to face.
    if (wantSimilar && reference && isVillain(reference)) {

        const villains = pool.filter(isVillain);

        if (villains.length) {
            return mostSimilar(villains, reference);
        }
    }

    return wantSimilar ? mostSimilar(pool, reference) : mostDifferent(pool, reference);
}


// A new, never-shown-this-run person for the slot next to
// `reference`, following the rules above.
function nextPerson(excluded, reference) {

    let found = chooseReplacement(excluded, reference);

    if (found) {
        state.seen.add(found.name);
        return found;
    }

    // Whole roster has been used up - start over, but keep
    // whoever is currently on screen out of the fresh pool.
    state.seen = new Set(excluded);

    found = chooseReplacement(excluded, reference);

    if (found) {
        state.seen.add(found.name);
    }

    return found;
}


function freshPair() {

    // The opening matchup is a straight random draw - two people
    // off the top of a shuffled deck, no stat business yet.
    // Everything after it goes through pairAround().
    const left = randomDraw(PEOPLE);
    const right = randomDraw(PEOPLE.filter((person) => person.name !== left.name));

    return [left, right];
}


// The next matchup, drawn around `reference` - the person the
// player just kept. The first card follows the rules above; the
// second is drawn around the first, so the two of them face off
// by the same logic. `excluded` is whoever is already involved.
function pairAround(reference, excluded) {

    const pool = new Set(excluded);

    const first = nextPerson(pool, reference);

    if (!first) {
        return freshPair();
    }

    pool.add(first.name);

    const second = nextPerson(pool, first);

    if (!second) {
        return freshPair();
    }

    return [first, second];
}


// One uniformly random person out of `pool`.
function randomDraw(pool) {
    return pool[Math.floor(Math.random() * pool.length)];
}


// ------------------------------------------
// STORAGE
// ------------------------------------------

function loadSession() {
    try {
        const raw = localStorage.getItem(STORAGE_PREFIX + state.key);

        return raw ? JSON.parse(raw) : null;
    } catch (error) {
        return null;
    }
}


function saveSession() {
    try {
        localStorage.setItem(STORAGE_PREFIX + state.key, JSON.stringify({
            seen: [...state.seen],
            slots: state.slots.filter(Boolean).map((person) => person.name),
            picks: state.picks,
            done: state.done
        }));
    } catch (error) {
        // Private browsing - the game still works, it just forgets.
    }
}


// ?reset=1 wipes the run so you can play again while testing.
function handleReset() {
    const params = new URLSearchParams(window.location.search);

    if (!params.has("reset")) {
        return;
    }

    clearRun();

    params.delete("reset");

    const query = params.toString();

    history.replaceState(
        {},
        "",
        window.location.pathname + (query ? `?${query}` : "")
    );
}


// Wipe the current run - and any run saved by an older version.
function clearRun() {
    try {
        localStorage.removeItem(STORAGE_PREFIX + state.key);

        const stale = [];

        for (let i = 0; i < localStorage.length; i++) {
            const key = localStorage.key(i);

            if (key && key.startsWith("rankdle:")) {
                stale.push(key);
            }
        }

        stale.forEach((key) => localStorage.removeItem(key));
    } catch (error) {
        // Nothing to wipe if storage is unavailable.
    }
}


// ------------------------------------------
// HELPERS
// ------------------------------------------

function initialsFor(name) {
    const ignored = new Set(["the", "a", "an", "of", "and"]);

    const words = name
        .split(/\s+/)
        .filter((word) => word.length > 1 && !ignored.has(word.toLowerCase()));

    const source = words.length ? words : name.split(/\s+/);

    if (source.length === 1) {
        return source[0].slice(0, 2).toUpperCase();
    }

    return (source[0][0] + source[1][0]).toUpperCase();
}


function byName(name) {
    return PEOPLE.find((person) => person.name === name) || null;
}


function formatDate(date) {
    return new Intl.DateTimeFormat("en-US", {
        month: "long",
        day: "numeric",
        year: "numeric"
    }).format(date);
}


// Everything goes into innerHTML, so every name and sentence is
// escaped first. The roster is our own data - this is just hygiene.
function esc(value) {
    return String(value)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;");
}


function plural(count, one, many) {
    return count === 1 ? one : many;
}


function joinWithAnd(items) {
    if (!items.length) {
        return "";
    }

    if (items.length === 1) {
        return items[0];
    }

    return `${items.slice(0, -1).join(", ")} and ${items[items.length - 1]}`;
}


// One decimal place, so averages read as 3.8 rather than 3.8153846.
function fmt1(value) {
    return (Math.round(value * 10) / 10).toFixed(1);
}


// A gap below its threshold is noise, not a pattern - zero it out
// so small differences can never name a run.
function clears(value, threshold) {
    return Math.abs(value) >= threshold ? value : 0;
}


// ------------------------------------------
// THE PROFILE
//
// Ten picks, read back as a personality.
//
// For every rating we compare the average of the people you took
// against the average of the people you turned down. The gap is
// the signal; a gap that small is noise and says so out loud.
// A few things are counted rather than averaged: gender is a
// head-to-head tally, fiction and evil picks are plain counts,
// and categories are scored by how often they won vs. lost.
// ------------------------------------------

const PROFILE = {
    // Minimum gaps before a dimension is worth a sentence.
    // Averages sit on a 0-5 scale, so 0.5 is a tenth of the range.
    moralityThreshold: 0.45,
    controversyThreshold: 0.4,
    fameThreshold: 0.4,
    eraThreshold: 0.55,

    // How many cards the read-out shows at most.
    maxInsights: 6,

    // A pick is called "controversial" at this rating or above.
    controversialCutoff: 4
};


function avgOf(list, key) {
    return list.length
        ? list.reduce((sum, person) => sum + person[key], 0) / list.length
        : 0;
}


function analyseProfile(picks) {

    const pairs = picks
        .map((pick) => ({ chosen: byName(pick.chosen), rejected: byName(pick.rejected) }))
        .filter((pair) => pair.chosen && pair.rejected);

    const chosen = pairs.map((pair) => pair.chosen);
    const rejected = pairs.map((pair) => pair.rejected);
    const total = pairs.length;

    // The whole read-out hangs off these four gaps.
    const morality = avgOf(chosen, "morality") - avgOf(rejected, "morality");
    const controversy = avgOf(chosen, "controversy") - avgOf(rejected, "controversy");
    const fame = avgOf(chosen, "fame") - avgOf(rejected, "fame");
    const era = avgOf(chosen, "era") - avgOf(rejected, "era");

    // Head-to-head tally: how often a woman beat a man and back.
    let womenBeatMen = 0;
    let menBeatWomen = 0;

    for (const pair of pairs) {
        if (pair.chosen.gender === 1 && pair.rejected.gender === 0) {
            womenBeatMen++;
        } else if (pair.chosen.gender === 0 && pair.rejected.gender === 1) {
            menBeatWomen++;
        }
    }

    const womenPicked = chosen.filter((person) => person.gender === 1).length;
    const menPicked = total - womenPicked;
    const genderTilt = womenBeatMen - menBeatWomen;

    // Counts that are more telling as raw numbers than as averages.
    const fictionPicked = chosen.filter((person) => person.fiction === 1).length;
    const fictionPassed = rejected.filter((person) => person.fiction === 1).length;
    const fictionTilt = fictionPicked - fictionPassed;

    const evilNames = [...new Set(
        pairs.filter((pair) => isEvil(pair.chosen)).map((pair) => pair.chosen.name)
    )];

    // "You handed a win to Adolf Hitler and Joseph Stalin - outright
    // villains." Names are deduped above, so a repeat pick can't
    // show up twice in the same sentence.
    const villainLine = () => {

        if (!evilNames.length) {
            return "";
        }

        const head = evilNames.length <= 2
            ? joinWithAnd(evilNames)
            : `${evilNames.slice(0, 2).join(", ")} and ${evilNames.length - 2} more`;

        return `You handed a win to ${head}${
            evilNames.length > 2 ? ", all" : " -"
        } outright ${plural(evilNames.length, "villain", "villains")}.`;
    };

    const scandalousPicked = chosen.filter(
        (person) => person.controversy >= PROFILE.controversialCutoff
    ).length;

    // The one-off calls worth singling out.
    let worstCall = null;
    let bestCall = null;

    for (const pair of pairs) {
        const drop = pair.rejected.morality - pair.chosen.morality;
        const gain = pair.chosen.morality - pair.rejected.morality;

        if (!worstCall || drop > worstCall.drop) {
            worstCall = { ...pair, drop };
        }

        if (!bestCall || gain > bestCall.gain) {
            bestCall = { ...pair, gain };
        }
    }

    // Categories: won minus lost across the ten matchups.
    const tagNet = new Map();

    for (const pair of pairs) {
        tagNet.set(pair.chosen.tag, (tagNet.get(pair.chosen.tag) || 0) + 1);
        tagNet.set(pair.rejected.tag, (tagNet.get(pair.rejected.tag) || 0) - 1);
    }

    const tagRank = [...tagNet.entries()].sort((a, b) => b[1] - a[1]);
    const [bestTag, bestTagNet] = tagRank[0] || [null, 0];
    const [worstTag, worstTagNet] = tagRank[tagRank.length - 1] || [null, 0];

    const tagCount = (tag, side) =>
        pairs.filter((pair) => pair[side].tag === tag).length;

    // ------------------------------------------
    // The sentences
    // ------------------------------------------

    const insights = [];

    const add = (insight) => {
        insights.push({ weight: 0, ...insight });
    };

    // Gender - a head-to-head tally, never an average.
    if (total && womenBeatMen !== menBeatWomen) {

        const winning = genderTilt > 0 ? "woman" : "man";
        const winningMany = genderTilt > 0 ? "women" : "men";
        const losing = genderTilt > 0 ? "man" : "woman";
        const losingMany = genderTilt > 0 ? "men" : "women";
        const wins = genderTilt > 0 ? womenBeatMen : menBeatWomen;
        const losses = genderTilt > 0 ? menBeatWomen : womenBeatMen;
        const pickedCount = genderTilt > 0 ? womenPicked : menPicked;
        const otherCount = total - pickedCount;

        add({
            label: "Gender",
            signature: true,
            weight: Math.abs(genderTilt),
            title: `You go for the ${winningMany}`,
            detail: `You picked a ${winning} over a ${losing} ${wins}-${losses} across ${
                wins + losses
            } mixed matchups. All in: ${pickedCount} ${
                plural(pickedCount, winning, winningMany)
            } and ${otherCount} ${plural(otherCount, losing, losingMany)} out of ${total}.`
        });
    } else if (total && womenBeatMen === 0) {
        add({
            label: "Gender",
            signature: true,
            weight: 0,
            title: "Gender never swayed you",
            detail: `Not one matchup crossed gender lines. You finished with ${womenPicked} ${
                plural(womenPicked, "woman", "women")
            } and ${menPicked} ${plural(menPicked, "man", "men")} out of ${total}, which is just the draw.`
        });
    } else if (total) {
        add({
            label: "Gender",
            signature: true,
            weight: 0,
            title: "You're dead even on gender",
            detail: `Every mixed matchup went both ways: ${womenBeatMen} women beat a man, ${menBeatWomen} men beat a woman. You finished on ${womenPicked} ${
                plural(womenPicked, "woman", "women")
            } and ${menPicked} ${plural(menPicked, "man", "men")}.`
        });
    }

    // Morality - the good / evil axis, plus anyone you handed a win to.
    const chosenMorality = fmt1(avgOf(chosen, "morality"));
    const passedMorality = fmt1(avgOf(rejected, "morality"));

    if (morality <= -PROFILE.moralityThreshold) {
        add({
            label: "Morality",
            signature: true,
            weight: Math.abs(morality) * 2.4,
            title: "You have a thing for the evil",
            detail: `Your picks average ${chosenMorality} out of 5 for morality. The people you passed on average ${passedMorality}. ${villainLine()}`.trim()
        });
    } else if (morality >= PROFILE.moralityThreshold) {
        add({
            label: "Morality",
            signature: true,
            weight: Math.abs(morality) * 2.4,
            title: "You default to the good guys",
            detail: `Your picks average ${chosenMorality} out of 5 for morality, against ${passedMorality} for the people you turned down. ${
                evilNames.length
                    ? `Even so, ${joinWithAnd(evilNames)} still got your vote.`
                    : "Not one outright villain got your vote."
            }`
        });
    } else {
        add({
            label: "Morality",
            signature: true,
            weight: 0,
            title: "Morality doesn't move you",
            detail: `Your picks average ${chosenMorality} out of 5 for morality against ${passedMorality} for the rejects - a wash. ${villainLine()}`.trim()
        });
    }

    // Controversy.
    const chosenControversy = fmt1(avgOf(chosen, "controversy"));
    const passedControversy = fmt1(avgOf(rejected, "controversy"));

    if (controversy >= PROFILE.controversyThreshold) {
        add({
            label: "Controversy",
            signature: true,
            weight: Math.abs(controversy) * 2.2,
            title: "You love a good scandal",
            detail: `Your picks average ${chosenControversy} out of 5 for controversy against ${passedControversy} for the people you dropped. ${scandalousPicked} of your ${total} ${
                plural(total, "pick", "picks")
            } sat in the top band of it.`
        });
    } else if (controversy <= -PROFILE.controversyThreshold) {
        add({
            label: "Controversy",
            signature: true,
            weight: Math.abs(controversy) * 2.2,
            title: "You like them controversy-free",
            detail: `Your picks average ${chosenControversy} out of 5 for controversy against ${passedControversy} for the people you passed on. Clean reputations win.`
        });
    } else {
        add({
            label: "Controversy",
            signature: true,
            weight: 0,
            title: "Controversy doesn't move you",
            detail: `${chosenControversy} against ${passedControversy} on the scandal scale - ${scandalousPicked} of your ${total} ${
                plural(total, "pick", "picks")
            } were properly controversial, and that was that.`
        });
    }

    // Fame.
    if (fame >= PROFILE.fameThreshold) {
        add({
            label: "Fame",
            weight: Math.abs(fame) * 1.8,
            title: "You're star-struck",
            detail: `Household names averaged ${fmt1(avgOf(chosen, "fame"))} out of 5 for fame in your picks, against ${fmt1(
                avgOf(rejected, "fame")
            )} for the people you walked past.`
        });
    } else if (fame <= -PROFILE.fameThreshold) {
        add({
            label: "Fame",
            weight: Math.abs(fame) * 1.8,
            title: "You root for the underdogs",
            detail: `Your picks average ${fmt1(
                avgOf(chosen, "fame")
            )} out of 5 for fame, while the people you passed on sit at ${fmt1(
                avgOf(rejected, "fame")
            )}. The less famous one kept winning.`
        });
    }

    // Era.
    if (era >= PROFILE.eraThreshold) {
        add({
            label: "Era",
            weight: Math.abs(era) * 1.7,
            title: "You live in the present",
            detail: `Your picks sit at ${fmt1(
                avgOf(chosen, "era")
            )} out of 5 for "modern", against ${fmt1(
                avgOf(rejected, "era")
            )} for the people you turned down. History lost.`
        });
    } else if (era <= -PROFILE.eraThreshold) {
        add({
            label: "Era",
            weight: Math.abs(era) * 1.7,
            title: "You're an old soul",
            detail: `Your picks average ${fmt1(
                avgOf(chosen, "era")
            )} out of 5 for "modern" - the people you passed on are closer to today at ${fmt1(
                avgOf(rejected, "era")
            )}. You kept reaching for the past.`
        });
    }

    // Fiction.
    if (fictionTilt >= 3) {
        add({
            label: "Fiction",
            weight: fictionTilt,
            title: "Your roster isn't real",
            detail: `You picked a fictional character ${fictionPicked} of ${total} times and turned down ${fictionPassed} more of them. Books, films and games beat real history.`
        });
    } else if (fictionTilt <= -3) {
        add({
            label: "Fiction",
            weight: Math.abs(fictionTilt),
            title: "You keep both feet in reality",
            detail: `Fictional characters won only ${fictionPicked} of your ${total} ${
                plural(total, "pick", "picks")
            }, and you passed on ${fictionPassed} more of them. Real people kept winning.`
        });
    }

    // Category affinity - only when a category really did dominate.
    if (bestTag && bestTagNet >= 3) {

        const won = tagCount(bestTag, "chosen");
        const turnedDown = tagCount(bestTag, "rejected");

        add({
            label: "Category",
            weight: bestTagNet,
            title: `You have a type: ${bestTag}`,
            detail: turnedDown
                ? `You picked someone from ${bestTag} ${won} ${
                    plural(won, "time", "times")
                } and turned down ${turnedDown}. It kept winning.`
                : `Every ${bestTag} that stood in front of you won - all ${won} ${
                    plural(won, "time", "times")
                }, not one passed over.`
        });
    }

    if (worstTag && worstTagNet <= -3 && worstTag !== bestTag) {

        const won = tagCount(worstTag, "chosen");
        const turnedDown = tagCount(worstTag, "rejected");

        add({
            label: "Blind spot",
            weight: Math.abs(worstTagNet),
            title: `You overlooked the ${worstTag}s`,
            detail: won
                ? `${worstTag}s stood in front of you ${turnedDown} ${
                    plural(turnedDown, "time", "times")
                } and you took only ${won}.`
                : `Not one ${worstTag} got past you - you passed on all ${turnedDown} that stood there.`
        });
    }

    // The single calls worth naming. They carry less weight than the
    // findings above - one matchup should not outshout a pattern.
    if (worstCall && worstCall.drop >= 2) {
        add({
            label: "Most questionable call",
            weight: worstCall.drop * 0.6,
            title: `${worstCall.chosen.name} over ${worstCall.rejected.name}`,
            detail: `A ${
                worstCall.drop
            }-point drop on morality - you handed the win to someone rated ${worstCall.chosen.morality} out of 5 over someone rated ${worstCall.rejected.morality}.`
        });
    }

    if (bestCall && bestCall.gain >= 2) {
        add({
            label: "Finest hour",
            weight: bestCall.gain * 0.5,
            title: `${bestCall.chosen.name} over ${bestCall.rejected.name}`,
            detail: `The most moral pick on the board: ${bestCall.chosen.morality} out of 5 against ${bestCall.rejected.morality}. It was the right call.`
        });
    }

    // The signature three always make the cut and always lead: gender,
    // morality and controversy are the personality; a one-off
    // standout is a footnote. Within each group, strongest first.
    const rank = (insight) => insight.weight + (insight.signature ? 100 : 0);

    const byStrength = [...insights].sort((a, b) => rank(b) - rank(a));

    const shown = [
        ...byStrength.filter((insight) => insight.signature),
        ...byStrength.filter((insight) => !insight.signature)
    ].slice(0, PROFILE.maxInsights);

    // ------------------------------------------
    // The headline
    // ------------------------------------------

    const tells = [];

    if (morality <= -PROFILE.moralityThreshold) tells.push("the downright evil");
    else if (morality >= PROFILE.moralityThreshold) tells.push("the righteous");

    if (controversy >= PROFILE.controversyThreshold) tells.push("the controversial");
    else if (controversy <= -PROFILE.controversyThreshold) tells.push("the controversy-free");

    if (fame >= PROFILE.fameThreshold) tells.push("the famous");
    else if (fame <= -PROFILE.fameThreshold) tells.push("the underdogs");

    if (era >= PROFILE.eraThreshold) tells.push("the modern");
    else if (era <= -PROFILE.eraThreshold) tells.push("the historical");

    if (fictionTilt >= 3) tells.push("the fictional");
    else if (fictionTilt <= -3) tells.push("the real");

    if (genderTilt >= 3) tells.push("the women");
    else if (genderTilt <= -3) tells.push("the men");

    const subtitle = tells.length
        ? `${total} picks, one pattern: you kept going back to ${joinWithAnd(tells)}.`
        : `${total} picks and no pattern worth naming - you played it straight down the middle.`;

    // Only a signal that cleared its threshold gets to name the run,
    // so the title and the sentence underneath always agree.
    const title = tells.length
        ? archetypeFor({
            morality: clears(morality, PROFILE.moralityThreshold),
            controversy: clears(controversy, PROFILE.controversyThreshold),
            fame: clears(fame, PROFILE.fameThreshold),
            era: clears(era, PROFILE.eraThreshold),
            fictionTilt: clears(fictionTilt, 3)
        })
        : "The Wildcard";

    // Chips are counts worth a glance; a zero is not worth one.
    const chips = [
        `${womenPicked} ${plural(womenPicked, "woman", "women")} / ${menPicked} ${
            plural(menPicked, "man", "men")
        }`
    ];

    if (fictionPicked) chips.push(`${fictionPicked} fictional`);
    if (evilNames.length) chips.push(`${evilNames.length} ${
        plural(evilNames.length, "villain", "villains")
    }`);
    if (scandalousPicked) chips.push(`${scandalousPicked} ${
        plural(scandalousPicked, "scandal", "scandals")
    }`);

    return {
        pairs,
        title,
        subtitle,
        insights: shown,
        chips,
        stats: [
            { label: "Morality", you: avgOf(chosen, "morality"), them: avgOf(rejected, "morality") },
            { label: "Controversy", you: avgOf(chosen, "controversy"), them: avgOf(rejected, "controversy") },
            { label: "Fame", you: avgOf(chosen, "fame"), them: avgOf(rejected, "fame") },
            { label: "Modernity", you: avgOf(chosen, "era"), them: avgOf(rejected, "era") }
        ]
    };
}


// The title over the whole read-out: whichever pattern is loudest,
// and only if it is loud enough to earn a name.
function archetypeFor({ morality, controversy, fame, era, fictionTilt }) {

    const up = (value) => Math.max(0, value);

    const candidates = [
        { title: "The Villain's Best Friend", score: up(-morality) * 2.4 + up(controversy) * 0.6 },
        { title: "The Drama Magnet", score: up(controversy) * 2.2 + up(-morality) * 0.4 },
        { title: "The Moral Compass", score: up(morality) * 2.4 },
        { title: "The Star-Struck", score: up(fame) * 2.2 },
        { title: "The Underdog's Biggest Fan", score: up(-fame) * 2.2 },
        { title: "The Daydreamer", score: up(fictionTilt / 3) * 2.6 },
        { title: "The Old Soul", score: up(-era) * 2 },
        { title: "The Crowd-Pleaser", score: up(era) * 2 }
    ];

    const loudest = candidates.reduce((best, candidate) =>
        candidate.score > best.score ? candidate : best
    );

    // Nothing cleared the bar: a run with no pattern gets no name.
    return loudest.score < 1 ? "The Wildcard" : loudest.title;
}


// ------------------------------------------
// RENDERING
// ------------------------------------------

const container = document.getElementById("people-container");


function cardMarkup(person) {
    const photo = person.image
        ? `<img src="${person.image}" alt="" loading="lazy">`
        : "";

    const tag = person.tag
        ? `<span class="person-tag">${person.tag}</span>`
        : "";

    return `
        <div class="portrait">
            <span class="initials" aria-hidden="true">${initialsFor(person.name)}</span>
            ${photo}
            ${tag}
        </div>
        <div class="person-info">
            <div class="person-text">
                <span class="person-name">${person.name}</span>
                <span class="person-meta">
                    <span class="person-years">${person.years}</span>
                    <span class="person-role">${person.role}</span>
                </span>
            </div>
            <span class="pick-btn" aria-hidden="true">
                <svg class="pick-arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 12h14"/><path d="M12.5 5.5 19 12l-6.5 6.5"/></svg>
                <svg class="pick-check" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12.5 10 17.5 19 7"/></svg>
            </span>
        </div>
    `;
}


function buildCard(person, index) {

    const card = document.createElement("div");

    card.className = "person-card";
    card.setAttribute("role", "button");
    card.dataset.name = person.name;
    card.dataset.id = String(person.id);
    card.dataset.index = String(index);
    card.dataset.tag = person.tag || "";
    card.innerHTML = cardMarkup(person);
    card.tabIndex = 0;

    const image = card.querySelector("img");

    if (image) {
        image.addEventListener("error", () => {
            card.classList.add("no-photo");
        });
    }

    card.setAttribute(
        "aria-label",
        `Pick ${person.name} as the better person. ${person.role}, ${person.years}.`
    );

    return card;
}


function render() {

    container.innerHTML = "";

    state.slots.forEach((person, index) => {

        if (!person) {
            return;
        }

        const card = buildCard(person, index);

        // The first paint and every new matchup: both cards rise
        // in, staggered, so a fresh round reads as a fresh round.
        if (state.initial || state.stagger) {
            card.classList.add("enter");
            card.style.animationDelay = `${index * 0.08}s`;
        }

        container.appendChild(card);
    });

    state.stagger = false;
    state.initial = false;
}


// ------------------------------------------
// PROGRESS
//
// Ten bars: filled is done, the wider one is now.
// ------------------------------------------

const progressEl = document.getElementById("progress");
const progressDots = document.getElementById("progress-dots");
const roundLabel = document.getElementById("round-label");
const hintEl = document.getElementById("hint");


function renderProgress() {

    if (state.done) {
        progressEl.hidden = true;
        return;
    }

    progressEl.hidden = false;

    const round = currentRound();
    const last = round === ROUNDS_TOTAL;

    roundLabel.textContent = last ? "Final pick" : `Pick ${round} of ${ROUNDS_TOTAL}`;
    hintEl.textContent = last
        ? "Last one. The profile follows this pick."
        : "Tap a card to choose.";

    progressDots.innerHTML = "";

    for (let i = 1; i <= ROUNDS_TOTAL; i++) {
        const dot = document.createElement("span");

        dot.className = "p-dot";

        if (i < round) dot.classList.add("is-done");
        if (i === round) dot.classList.add("is-now");

        progressDots.appendChild(dot);
    }
}


// ------------------------------------------
// PICKING
// ------------------------------------------

function pick(index) {

    if (state.busy || state.done || !state.slots[index]) {
        return;
    }

    const other = 1 - index;
    const kept = state.slots[index];
    const replaced = state.slots[other];

    state.busy = true;

    // Record the decision - this is all the profile is built from.
    state.picks.push({ chosen: kept.name, rejected: replaced.name });

    const finalPick = state.picks.length >= ROUNDS_TOTAL;

    // Draw the next matchup straight away so it is ready the
    // moment the animation lands. Both cards leave on every pick:
    // ten picks should be ten decisions, not one card winning a
    // rematch. The tenth pick has nobody coming in.
    const nextPair = finalPick
        ? null
        : pairAround(kept, new Set([kept.name, replaced.name]));

    const cards = [...container.children];

    // The pick lights up for a beat...
    if (cards[index]) cards[index].classList.add("chosen");

    renderProgress();

    // ...then both cards clear out and the new pair rises in.
    window.setTimeout(() => {

        if (cards[other]) cards[other].classList.add("replaced");

        // The winner holds a moment longer than the loser.
        window.setTimeout(() => {
            if (cards[index]) cards[index].classList.add("replaced");
        }, SWAP_DELAY);

        window.setTimeout(() => {

            if (finalPick) {
                state.done = true;
                saveSession();
                showResults();
                return;
            }

            state.slots = nextPair;
            state.stagger = true;

            saveSession();
            render();
            renderProgress();

            state.busy = false;

        }, FADE_DELAY + SWAP_DELAY);

    }, HOLD_DELAY);
}


container.addEventListener("click", (event) => {

    const card = event.target.closest(".person-card");

    if (!card) {
        return;
    }

    pick(Number(card.dataset.index));
});


// Enter or Space on a focused card picks it, like the button it is.
container.addEventListener("keydown", (event) => {

    if (event.key !== "Enter" && event.key !== " ") {
        return;
    }

    const card = event.target.closest(".person-card");

    if (!card) {
        return;
    }

    event.preventDefault();
    pick(Number(card.dataset.index));
});


// The card lights up under the cursor rather than glowing at random.
container.addEventListener("pointermove", (event) => {

    const card = event.target.closest(".person-card");

    if (!card) {
        return;
    }

    const box = card.getBoundingClientRect();

    card.style.setProperty("--mx", `${event.clientX - box.left}px`);
    card.style.setProperty("--my", `${event.clientY - box.top}px`);
});


// ------------------------------------------
// THE READ-OUT
// ------------------------------------------

const heroEl = document.getElementById("hero");
const duelEl = document.getElementById("duel-section");
const resultsEl = document.getElementById("results");
const resultsTitle = document.getElementById("results-title");
const resultsSub = document.getElementById("results-sub");
const chipsEl = document.getElementById("results-chips");
const insightsEl = document.getElementById("insights");
const statsEl = document.getElementById("stats");
const recapEl = document.getElementById("recap");
const copyBtn = document.getElementById("copy-results");
const playAgainBtn = document.getElementById("play-again");

// Kept around for the copy button.
let lastProfile = null;


// The rating bars run 0-5, so a raw average is also a percentage.
function barWidth(value) {
    return Math.max(0, Math.min(100, Math.round((value / 5) * 100)));
}


function showResults() {

    const profile = analyseProfile(state.picks);

    lastProfile = profile;
    state.done = true;
    state.busy = false;

    resultsTitle.textContent = profile.title;
    resultsSub.textContent = profile.subtitle;

    chipsEl.innerHTML = profile.chips
        .map((chip) => `<span class="chip">${esc(chip)}</span>`)
        .join("");

    insightsEl.innerHTML = profile.insights
        .map((insight, index) => `
            <article class="insight" style="--i:${index}">
                <span class="insight-label">${esc(insight.label)}</span>
                <h3 class="insight-title">${esc(insight.title)}</h3>
                <p class="insight-detail">${esc(insight.detail)}</p>
            </article>`)
        .join("");

    statsEl.innerHTML =
        profile.stats.map((stat) => `
            <div class="stat">
                <div class="stat-head">
                    <span class="stat-name">${esc(stat.label)}</span>
                    <span class="stat-nums"><b>${fmt1(stat.you)}</b> vs ${fmt1(stat.them)}</span>
                </div>
                <div class="stat-bars">
                    <div class="stat-track"><div class="stat-fill you" style="width:${barWidth(stat.you)}%"></div></div>
                    <div class="stat-track"><div class="stat-fill them" style="width:${barWidth(stat.them)}%"></div></div>
                </div>
            </div>`).join("") +
        `<div class="stat-legend">
            <span><i class="swatch you" aria-hidden="true"></i>What you took</span>
            <span><i class="swatch them" aria-hidden="true"></i>What you passed on</span>
        </div>`;

    recapEl.innerHTML = profile.pairs
        .map((pair, index) => `
            <li class="recap-item">
                <span class="recap-n">${index + 1}</span>
                <span class="recap-won">${esc(pair.chosen.name)}</span>
                <span class="recap-over">over</span>
                <span class="recap-lost">${esc(pair.rejected.name)}</span>
            </li>`)
        .join("");

    heroEl.hidden = true;
    duelEl.hidden = true;
    resultsEl.hidden = false;

    renderProgress();

    window.scrollTo({ top: 0, behavior: "smooth" });
}


// Plain text for the clipboard - the whole profile in one block.
function profileText(profile) {

    const picks = profile.pairs
        .map((pair, index) => `${index + 1}. ${pair.chosen.name} over ${pair.rejected.name}`)
        .join("\n");

    return [
        `RANKDLE - ${profile.title}`,
        profile.subtitle,
        "",
        ...profile.insights.map((insight) => `- ${insight.title} (${insight.label}): ${insight.detail}`),
        "",
        "My picks:",
        picks
    ].join("\n");
}


copyBtn.addEventListener("click", async () => {

    if (!lastProfile) {
        return;
    }

    const text = profileText(lastProfile);

    try {
        await navigator.clipboard.writeText(text);
    } catch (error) {
        // Clipboard blocked - over http or in an old browser. Ask.
        window.prompt("Copy your profile:", text);
    }

    const was = copyBtn.textContent;

    copyBtn.textContent = "Copied";
    copyBtn.disabled = true;

    window.setTimeout(() => {
        copyBtn.textContent = was;
        copyBtn.disabled = false;
    }, 1600);
});


playAgainBtn.addEventListener("click", () => {
    clearRun();
    window.location.href = window.location.pathname;
});


// ------------------------------------------
// START
// ------------------------------------------

handleReset();

document.getElementById("today-date").textContent =
    formatDate(new Date()).toUpperCase();


// Put a saved run back together: the people on screen, everyone
// already shown, and every pick made so far.
function restoreRun() {

    const saved = loadSession();

    if (!saved) {
        return;
    }

    if (Array.isArray(saved.seen)) {
        saved.seen.forEach((name) => {
            if (byName(name)) {
                state.seen.add(name);
            }
        });
    }

    if (Array.isArray(saved.picks)) {
        state.picks = saved.picks
            .filter((pick) =>
                pick &&
                typeof pick.chosen === "string" &&
                typeof pick.rejected === "string" &&
                pick.chosen !== pick.rejected &&
                byName(pick.chosen) &&
                byName(pick.rejected)
            )
            .slice(0, ROUNDS_TOTAL);
    }

    // A finished run is only finished if all ten picks are there.
    state.done = saved.done === true && state.picks.length >= ROUNDS_TOTAL;

    if (
        !state.done &&
        Array.isArray(saved.slots) &&
        saved.slots.length === 2 &&
        saved.slots[0] !== saved.slots[1] &&
        saved.slots.every((name) => byName(name))
    ) {
        state.slots = saved.slots.map(byName);
    }
}


if (!Array.isArray(PEOPLE) || PEOPLE.length < 3) {

    container.innerHTML =
        "<p class='hint'>No people loaded. Run <code>node tools/build.mjs</code> first.</p>";

} else {

    restoreRun();

    if (state.done) {
        showResults();
    } else {

        // A fresh run opens on a completely random pair; a saved one
        // picks up exactly where it was left.
        if (!state.slots[0] || !state.slots[1]) {
            state.slots = freshPair();
        }

        state.slots.forEach((person) => state.seen.add(person.name));

        renderProgress();
        render();
    }
}
